import * as React from "react";
import { Row, RowData, Table } from "@tanstack/react-table";
import Checkbox from "../../Checkbox";

export const SELECT_COLUMN_ID = "__table__selection__";

type selectHeader<T> = { table: Table<T> };

const SelectHeader = <T extends RowData>({ table }: selectHeader<T>) => {
  const selection = table.getSelectedRowModel().flatRows.length;
  const totalRows = table.getCoreRowModel().rows.length;
  const selectionMode = table.options.meta?.selectionMode;
  // FIXME: to be removed when merging the indeterminate fix
  const max =
    selectionMode === "page"
      ? table.getPaginationRowModel().rows.length
      : totalRows;

  const calcIndeterminate =
    selection > 0 && selection < max
      ? {
          indeterminate: true, //to be removed later when indeterminate logic is fixed in checkbox
          checked: true,
        }
      : null;

  return (
    <Checkbox
      checked={
        selectionMode === "page"
          ? table.getIsAllPageRowsSelected()
          : table.getIsAllRowsSelected()
      }
      indeterminate={
        selectionMode === "page"
          ? table.getIsSomePageRowsSelected()
          : table.getIsSomeRowsSelected()
      }
      onChange={(e) => {
        selectionMode === "page"
          ? table.getToggleAllPageRowsSelectedHandler()(e)
          : table.getToggleAllRowsSelectedHandler()(e);
      }}
      {...calcIndeterminate}
    />
  );
};

const selectableColumn = {
  id: SELECT_COLUMN_ID,
  header: <T extends RowData>({ table }: selectHeader<T>) => (
    <SelectHeader table={table} />
  ),
  cell: <T extends RowData>({ row }: { row: Row<T> }) => (
    <Checkbox
      checked={row.getIsSelected()}
      disabled={!row.getCanSelect()}
      indeterminate={row.getIsSomeSelected()}
      labelProps={{ "ads-cell-type": SELECT_COLUMN_ID }}
      onClick={(e) => {
        row.getToggleSelectedHandler()(e);
      }}
    />
  ),
  disableResizing: true,
  disableSortBy: true,
};

export { selectableColumn };
